/** @jest-environment node */

const https = require('https');
const { fetchTranslations } = require('../fetchTranslations');

jest.mock('https');

describe('fetchTranslations', () => {
  const config = {
    apiBaseUrl: 'https://api.applanga.com/v1/api',
    bearerToken: 'token',
    requestedTagIds: ['tag-1'],
    queryParams: { app: 'app-id' },
  };

  beforeEach(() => {
    jest.clearAllMocks();
    jest.spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    console.log.mockRestore();
  });

  function mockHttpsResponse({ statusCode = 200, body = '{"ok":true}', requestError = null } = {}) {
    https.get.mockImplementation((url, options, callback) => {
      if (requestError) {
        const request = {
          on: jest.fn((event, handler) => {
            if (event === 'error') handler(requestError);
          }),
        };
        return request;
      }

      const response = {
        statusCode,
        on: jest.fn((event, handler) => {
          if (event === 'data') handler(body);
          if (event === 'end') handler();
        }),
      };

      callback(response);

      return {
        on: jest.fn(),
      };
    });
  }

  it('resolves parsed JSON on HTTP 200', async () => {
    mockHttpsResponse({ body: '{"data":{"en-US":{}}}' });

    await expect(fetchTranslations(config)).resolves.toEqual({ data: { 'en-US': {} } });
    expect(https.get).toHaveBeenCalled();
  });

  it('rejects on non-200 status', async () => {
    mockHttpsResponse({ statusCode: 500, body: 'error' });

    await expect(fetchTranslations(config)).rejects.toThrow('API returned status 500');
  });

  it('rejects on invalid JSON', async () => {
    mockHttpsResponse({ body: 'not-json' });

    await expect(fetchTranslations(config)).rejects.toThrow('Error parsing JSON');
  });

  it('rejects on network error', async () => {
    mockHttpsResponse({ requestError: new Error('network down') });

    await expect(fetchTranslations(config)).rejects.toThrow('Request error: network down');
  });
});
